<?php

declare(strict_types=1);

namespace App\PHPStan\Rules;

use PhpParser\Node;
use PhpParser\Node\Expr\MethodCall;
use PhpParser\Node\Identifier;
use PHPStan\Analyser\Scope;
use PHPStan\Rules\Rule;
use PHPStan\Rules\RuleErrorBuilder;

/**
 * Crystallized PHPStan AST Rule generated by the Hermes Self-Evolution Engine.
 * Catches direct $this->get() calls in Symfony controllers at Phase 1 for 0 LLM tokens.
 *
 * @implements Rule<MethodCall>
 */
final class NoGetInControllerRule implements Rule
{
    public function getNodeType(): string
    {
        return MethodCall::class;
    }

    /**
     * @param MethodCall $node
     * @return list<\PHPStan\Rules\IdentifierRuleError>
     */
    public function processNode(Node $node, Scope $scope): array
    {
        if (!$node->name instanceof Identifier) {
            return [];
        }

        $methodName = $node->name->toLowerString();
        if ($methodName !== 'get' && $methodName !== 'getparameter') {
            return [];
        }

        $classReflection = $scope->getClassReflection();
        if ($classReflection === null) {
            return [];
        }

        if (!$classReflection->isSubclassOf('Symfony\Bundle\FrameworkBundle\Controller\AbstractController') &&
            !$classReflection->isSubclassOf('Symfony\Bundle\FrameworkBundle\Controller\Controller')) {
            return [];
        }

        return [
            RuleErrorBuilder::message(sprintf(
                'Prohibited Service Locator call "$this->%s()" detected in controller "%s". Inject dependencies or parameters via constructor property promotion.',
                $node->name->name,
                $classReflection->getName()
            ))
            ->identifier('symfony.noServiceLocatorInController')
            ->line($node->getLine())
            ->build(),
        ];
    }
}
